"Jour de récupération : récupération active, mobilité, vélo très facile.": "Recovery day: active recovery, mobility, very easy cycling.",
"Jour d'entraînement et récupération élevée : séance complète.": "Training day and high recovery: full session.",
"Jour d'entraînement, récupération modérée : garde la qualité, coupe 20 à 30 % du volume.": "Training day, moderate recovery: keep the quality, cut volume by 20 to 30%.",
