"Hommes 20-39 ans : moyenne ≈ 70 bpm (NHANES). Sportifs d'endurance : 40 à 55.": "Men aged 20-39: average ≈ 70 bpm (NHANES). Endurance athletes: 40 to 55.",
"VFC nocturne des hommes de": "Overnight HRV of men aged",
