"ms (données de montres, valeur indicative).": "ms (watch data, indicative value).",
"Jeunes adultes : 7 h en moyenne mesurées par montre. Recommandé aux athlètes : 8 à 10 h.": "Young adults: 7 h on average measured by watch. Recommended for athletes: 8 to 10 h.",
"Hommes de {} ans : médiane ≈ {} ml/kg/min (registre FRIEND). Sprinteurs : souvent 50 à 58.": "Men aged {}: median ≈ {} ml/kg/min (FRIEND registry). Sprinters: often 50 to 58.",
"Hommes de {} ans en bonne santé : ≈ {} m/s. Plus bas = artères plus souples.": "Healthy men aged {}: ≈ {} m/s. Lower = more flexible arteries.",
"Hommes de": "Men aged",
"% de masse grasse (mesures DXA de NHANES, Kelly 2009). Zone saine : 8 à 19 % (Gallagher 2000). Sprinteurs de haut niveau : 6 à 10 %.": "% body fat (NHANES DXA measurements, Kelly 2009). Healthy range: 8 to 19% (Gallagher 2000). Elite sprinters: 6 to 10%.",
"Hommes non entraînés : ≈ 19,5 (Kouri 1995). Athlétique : 21 à 22. Sprinteurs de haut niveau : 22 à 24.": "Untrained men: ≈ 19.5 (Kouri 1995). Athletic: 21 to 22. Elite sprinters: 22 to 24.",
"moyenne": "average",
