"ajouté": "added",
"Saut supprimé": "Jump deleted",
"Pose le téléphone au sol ou sur un support à 1 à 1,5 m, bien de côté ou de face, cadré sur tes pieds. Filme en mode Ralenti (240 images/s, sinon 120).": "Put the phone on the ground or on a stand 1 to 1.5 m away, square from the side or the front, framed on your feet. Film in Slow-mo (240 fps, otherwise 120).",
"Pour que la mesure soit juste : jambes tendues et pointes de pieds en l'air, atterris sur les mêmes jambes tendues. Plier les genoux en vol rallonge le temps de vol et gonfle la hauteur.": "For an accurate measurement: legs straight and toes up in the air, land on the same straight legs. Bending your knees in the air lengthens flight time and inflates the height.",
"Pose des plots à 0, 5, 10, 15, 20, 25 et 30 m, et un deuxième plot en face de chacun de l'autre côté du couloir. Téléphone sur un pied à hauteur de hanche, perpendiculaire à la piste, à 10 à 15 m sur le côté, en face des 15 m, pour voir de 0 à 30 m. Tu marques l'image où ta hanche passe la ligne entre deux plots : c'est ce qui évite l'erreur de perspective. Filme en Ralenti.": "Put cones at 0, 5, 10, 15, 20, 25 and 30 m, and a second cone opposite each one on the other side of the lane. Phone on a tripod at hip height, perpendicular to the track, 10 to 15 m to the side, level with the 15 m mark, to see from 0 to 30 m. You mark the frame where your hip crosses the line between two cones: that avoids the perspective error. Film in Slow-mo.",
"Place le téléphone sur un pied, de côté, au niveau de la ligne d'arrivée, perpendiculaire à la piste, avec la ligne de départ aussi dans le cadre (donc loin, ou sur 5 à 10 m). Filme en Ralenti.": "Put the phone on a tripod, side-on, level with the finish line, perpendicular to the track, with the start line also in frame (so far away, or over 5 to 10 m). Film in Slow-mo.",
"Saut vertical avec contre-mouvement, mains sur les hanches. Ta force explosive de référence.": "Countermovement vertical jump, hands on hips. Your benchmark explosive strength.",
"Décollage": "Take-off",
"première image où les deux pieds ont quitté le sol": "first frame where both feet have left the ground",
"première image où un pied retouche le sol": "first frame where a foot touches the ground again",
"Le même saut avec l'élan des bras (Abalakov). L'écart avec le CMJ montre ta coordination des bras.": "The same jump with an arm swing (Abalakov). The gap with the CMJ shows your arm coordination.",
"Départ arrêté genoux à 90° pendant 2 s, sans redescendre. Avec des charges (+20, +40, +60 kg), il donne ton profil force-vitesse.": "Static start with knees at 90° for 2 s, without dipping. With loads (+20, +40, +60 kg), it gives your force-velocity profile.",
"Une jambe puis l'autre : l'écart gauche/droite montre ton asymétrie.": "One leg then the other: the left/right gap shows your asymmetry.",
"Un CMJ où l'on mesure aussi le temps entre le début de la descente et le décollage : ta capacité à sauter haut et vite.": "A CMJ where we also measure the time between the start of the descent and take-off: your ability to jump high and fast.",
"Début de la descente": "Start of the descent",
"première image où les hanches commencent à descendre": "first frame where the hips start going down",
"Tombe d'une box (30 à 40 cm) et rebondis le plus haut et le plus vite possible. Donne contact, RSI et raideur.": "Drop from a box (30 to 40 cm) and rebound as high and as fast as possible. Gives contact, RSI and stiffness.",
"première image où les pieds touchent le sol après la chute": "first frame where the feet touch the ground after the drop",
"Un saut puis 10 rebonds enchaînés, le plus haut avec le moins de contact. On garde la moyenne de tes 5 meilleurs RSI.": "One jump then 10 rebounds in a row, as high as possible with the least contact. We keep the average of your 5 best RSIs.",
"Rebonds chevilles raides, genoux presque tendus. Donne contact, RSI et raideur de cheville.": "Rebounds with stiff ankles, knees almost straight. Gives contact, RSI and ankle stiffness.",
"Sprint maximal de 30 m depuis un départ debout ou en 3 appuis. Tes passages tous les 5 m donnent ton profil force-vitesse horizontal.": "Maximal 30 m sprint from a standing or 3-point start. Your splits every 5 m give your horizontal force-velocity profile.",
"Départ": "Start",
"première image où tu bouges": "first frame where you move",
"image où la hanche passe la ligne des": "frame where the hip crosses the line at",
"Sprint chronométré": "Timed sprint",
"Ton temps sur 10, 20, 30 ou 60 m, ou un 5-0-5, sans cellules.": "Your time over 10, 20, 30 or 60 m, or a 5-0-5, without timing gates.",
"première image où le pied arrière quitte le sol": "first frame where the back foot leaves the ground",
"Arrivée": "Finish",
"première image où le buste passe la ligne": "first frame where the torso crosses the line",
"Tests pliométriques": "Plyometric tests",
"Touche un test, puis Commencer : tu poses le téléphone, tu sautes, et tu repères les images de décollage et d'atterrissage. L'appli calcule tout. La vidéo reste sur ton téléphone.": "Tap a test, then Start: you set the phone down, you jump, and you find the take-off and landing frames. The app calculates everything. The video stays on your phone.",
