"Marque dans l'ordre : décollage du premier saut, puis à chaque rebond atterrissage puis décollage, et le dernier atterrissage. {} repère{}.": "Mark in order: take-off of the first jump, then for each rebound landing then take-off, and the last landing. {} mark{}.",
