"Enregistrer": "Save",
"Le protocole": "The protocol",
"· touche pour l'ouvrir": "· tap to open it",
"touche pour l'ouvrir": "tap to open it",
"Échauffement général 5 à 10 min. Puis 10 répétitions à 50 %, 5 à 70 %, 3 à 80 %, 1 à 90 % de la charge visée. Ensuite des essais à la charge visée, 3 à 5 min de récup, 4 essais au plus : +2,5 à 5 % après une réussite. Choisis le nombre de répétitions du test (1 à 5RM) : plus il est bas, plus le 1RM est exact.": "General warm-up 5 to 10 min. Then 10 reps at 50%, 5 at 70%, 3 at 80%, 1 at 90% of the target load. Then attempts at the target load, 3 to 5 min rest, 4 attempts at most: +2.5 to 5% after a success. Choose the number of reps for the test (1 to 5RM): the lower it is, the more accurate the 1RM.",
"Indique la charge": "Enter the load",
"Plus de tests": "More tests",
"Importer de My Jump": "Import from My Jump",
"Pour récupérer tous tes résultats My Jump dans l'appli :": "To get all your My Jump results into the app:",
"1. Dans My Jump, ouvre tes résultats et touche": "1. In My Jump, open your results and tap",
": les sauts arrivent tout seuls dans Mes max en saut.": ": the jumps arrive by themselves in My jump maxes.",
"3. Sinon, enregistre le fichier et choisis-le ici. Les sauts déjà importés ne sont jamais comptés deux fois.": "3. Otherwise, save the file and choose it here. Jumps already imported are never counted twice.",
"Choisir le fichier My Jump": "Choose the My Jump file",
"Noter un résultat à la main": "Log a result by hand",
"box jump, longueur, triple bond, ou un saut mesuré ailleurs": "box jump, long jump, triple jump, or a jump measured elsewhere",
"N/kg": "N/kg",
"Le modèle colle mal à tes passages : un repère est sûrement décalé. Revois les passages.": "The model fits your splits poorly: a mark is probably off. Check the splits again.",
"Profil force-vitesse en sprint": "Sprint force-velocity profile",
"Échauffement": "Warm-up",
"Résultat": "Result",
"on": "on",
"Suivant": "Next",
"Retour": "Back",
"Ce test donne ta force horizontale au départ (F0), ta vitesse max théorique (V0), ta puissance (Pmax) et ton efficacité à orienter la force vers l'avant (RF, DRF). Avec un traîneau, il donne aussi la charge qui correspond à chaque objectif.": "This test gives your horizontal force at the start (F0), your theoretical max speed (V0), your power (Pmax) and your efficiency at directing force forwards (RF, DRF). With a sled, it also gives the load that matches each goal.",
"Il te faut :": "You need:",
"14 plots, un décamètre, un pied pour le téléphone, et un traîneau si tu veux le profil chargé.": "14 cones, a measuring tape, a tripod for the phone, and a sled if you want the loaded profile.",
"Température": "Temperature",
"pour la résistance de l'air": "for air resistance",
"La taille et la masse servent à calculer la surface que tu opposes à l'air.": "Height and mass are used to calculate the surface you present to the air.",
"1. 8 min de footing, mobilité de hanche et de cheville.": "1. 8 min jog, hip and ankle mobility.",
"3. 3 accélérations de 30 m à 70, 80 et 90 %, retour en marchant.": "3. 3 accelerations over 30 m at 70, 80 and 90%, walk back.",
"4. 3 min de repos avant le premier sprint.": "4. 3 min rest before the first sprint.",
"à fond jusqu'à 30 m, toujours le même départ. 4 à 5 min de récup entre deux sprints, 6 à 8 min avec traîneau.": "all-out to 30 m, always the same start. 4 to 5 min rest between sprints, 6 to 8 min with a sled.",
"Échauffement fait": "Warm-up done",
"Traîneau": "Sled",
"Sans charge": "Unloaded",
"Vmax {} m/s · F0 {} N/kg · Pmax {} W/kg · 30 m en {} s": "Vmax {} m/s · F0 {} N/kg · Pmax {} W/kg · 30 m in {} s",
"Profil charge-vitesse prêt ({} charges).": "Load-velocity profile ready ({} loads).",
"Fais 2 sprints sans charge, le meilleur compte. Pour le profil chargé, ajoute 2 à 4 charges de traîneau (par exemple 20, 40, 60 % de ta masse).": "Do 2 unloaded sprints, the best one counts. For the loaded profile, add 2 to 4 sled loads (for example 20, 40, 60% of your body mass).",
"Filmer un sprint sans charge": "Film an unloaded sprint",
"Charge du traîneau": "Sled load",
"Frottement du traîneau (μ)": "Sled friction (μ)",
"0,35 sur piste synthétique, plus sur herbe": "0.35 on a synthetic track, more on grass",
"Filmer un sprint avec traîneau": "Film a sled sprint",
"Voir mon profil": "See my profile",
"Il faut au moins un sprint sans charge.": "You need at least one unloaded sprint.",
"Retour aux sprints": "Back to the sprints",
"Ton RF max est bas : au départ, tu pousses trop vers le haut. Priorité aux départs chargés (traîneau lourd, côtes courtes) et à la position du buste.": "Your max RF is low: at the start, you push too much upwards. Prioritise loaded starts (heavy sled, short hills) and torso position.",
"Ta force vers l'avant chute vite avec la vitesse (DRF très négatif) : travaille l'efficacité à vitesse élevée (sprints lancés, traîneau léger).": "Your forward force drops quickly with speed (very negative DRF): work on efficiency at high speed (flying sprints, light sled).",
"RF et DRF dans les normes du sprint. Il n’existe pas de profil horizontal optimal publié : compare-toi d’un test à l’autre. F0 qui monte = meilleure accélération, V0 qui monte = meilleure vitesse max.": "RF and DRF within sprint norms. There is no published optimal horizontal profile: compare yourself from one test to the next. Rising F0 = better acceleration, rising V0 = better max speed.",
"Charges de traîneau": "Sled loads",
"Charge qui t'arrêterait (L0)": "Load that would stop you (L0)",
"−10 % de vitesse : technique, vitesse": "−10% speed: technique, speed",
"−30 % : accélération": "−30%: acceleration",
"La vitesse max baisse en ligne droite avec la charge (Cross 2017) : −50 % de vitesse = la charge où ta puissance horizontale est la plus haute.": "Max speed drops in a straight line with load (Cross 2017): −50% speed = the load where your horizontal power is highest.",
