"5 à 10 min de cardio léger et de mobilité, puis ces séries. Touche « Fait » pour lancer la récup.": "5 to 10 min of light cardio and mobility, then these sets. Tap \"Done\" to start the rest timer.",
"2 · Essais à 5 répétitions": "2 · 5-rep attempts",
