"Pour chaque exercice : échauffe les deux côtés, commence par ta jambe la plus faible, même technique et même amplitude, 2 min entre les côtés. Au-dessus de 10 % d'écart, c'est à corriger.": "For each exercise: warm up both sides, start with your weaker leg, same technique and same range, 2 min between sides. Above a 10% gap, it needs fixing.",
