"Matériel": "Equipment",
"Sauts chargés": "Loaded jumps",
"Ce test mesure ta force maximale (F0), ta vitesse maximale (V0) et ta puissance (Pmax) en poussée verticale. Il te dit surtout si tu dois travailler": "This test measures your maximal force (F0), your maximal velocity (V0) and your power (Pmax) in vertical push-off. Above all it tells you whether you should work on",
"plus de force ou plus de vitesse": "more strength or more speed",
"pour sauter et accélérer plus fort.": "to jump and accelerate harder.",
"une barre et des disques (ou un gilet lesté), un banc ou une box pour régler l'angle de 90°, un mètre ruban, et le téléphone sur un support.": "a bar and plates (or a weighted vest), a bench or box to set the 90° angle, a tape measure, and the phone on a stand.",
"Durée :": "Duration:",
"25 min environ. 5 charges (sans charge, +20, +40, +60, +80 kg), 2 essais par charge, 2 min de récup.": "about 25 min. 5 loads (unloaded, +20, +40, +60, +80 kg), 2 attempts per load, 2 min rest.",
"Ces mesures servent à calculer ta distance de poussée. Prends-les une fois, l'appli les garde.": "These measurements are used to calculate your push-off distance. Take them once, the app keeps them.",
"ta balance Withings": "your Withings scale",
"Longueur de jambe": "Leg length",
"allongé, du grand trochanter (os saillant sur le côté de la hanche) au bout des orteils, pied en pointe": "lying down, from the greater trochanter (the bony point on the side of the hip) to the tip of the toes, foot pointed",
"Hauteur à 90°": "Height at 90°",
"en position de départ, genoux à 90°, du sol au grand trochanter. Règle le banc à cette hauteur.": "in the starting position, knees at 90°, from the ground to the greater trochanter. Set the bench to this height.",
"Distance de poussée": "Push-off distance",
"1. 5 min de vélo ou de footing léger.": "1. 5 min of easy cycling or jogging.",
"2. Mobilité : chevilles, hanches, 10 squats au poids du corps.": "2. Mobility: ankles, hips, 10 bodyweight squats.",
"3. 5 squat jumps sous-maximaux, puis 2 à fond.": "3. 5 submaximal squat jumps, then 2 all-out.",
"La technique, à chaque saut :": "Technique, on every jump:",
"descends jusqu'à toucher le banc (90°),": "go down until you touch the bench (90°),",
", puis pousse le plus vite possible": ", then push as fast as possible",
"sans redescendre avant": "without dipping first",
". Barre bien tenue sur les épaules. Jambes tendues en l'air, atterris jambes tendues. Un contre-mouvement fausse le test : refais l'essai.": ". Bar held firmly on the shoulders. Legs straight in the air, land with straight legs. A countermovement skews the test: redo the attempt.",
"pas encore sauté": "not jumped yet",
"Encore": "More",
"Déjà {} charges : profil à {} % de l'optimal.": "Already {} loads: profile at {}% of optimal.",
"Pour chaque charge : « Filmer », fais ton saut, marque le décollage et l'atterrissage. 2 essais, le meilleur compte. Tu peux aussi taper la hauteur si tu l'as mesurée ailleurs. Arrête-toi quand tu sautes moins de 10 cm.": "For each load: \"Film\", do your jump, mark take-off and landing. 2 attempts, the best one counts. You can also type the height if you measured it elsewhere. Stop when you jump less than 10 cm.",
