"Garde l'équilibre entre force et vitesse ; continue à faire monter la puissance.": "Keep the balance between strength and speed; keep pushing your power up.",
"Les points sont peu alignés : un essai est sûrement raté (contre-mouvement, mauvais repère). Refais la charge qui s'écarte.": "The points are poorly aligned: an attempt was probably off (countermovement, wrong mark). Redo the load that sticks out.",
