"Dans ton planning :": "In your schedule:",
"Écris le temps que Google Maps annonce. L'appli le corrige : à vélo, tu vas 1,6 fois plus vite ; en voiture, elle ajoute les bouchons de Lille selon l'heure. Puis une marge de {} min à vélo et {} min en voiture (garer la voiture), pour arriver toujours un peu en avance.": "Type the time Google Maps gives. The app corrects it: by bike, you go 1.6 times faster; by car, it adds Lille traffic depending on the time. Then a margin of {} min by bike and {} min by car (parking the car), so you always arrive a little early.",
"Avant et après la muscu, c'est le trajet de la salle choisie pour la séance (sinon la dernière où tu es allé). Maison : pas de trajet.": "Before and after the gym, it's the trip to the gym chosen for the session (otherwise the last one you went to). Home: no trip.",
