"protéines": "protein",
"Clique un bloc pour le voir · glisse-le pour le déplacer, même vers un autre jour · tire un bord pour changer la durée · double-clic pour le modifier · molette pour parcourir la journée": "Click a block to see it · drag it to move it, even to another day · pull an edge to change the duration · double-click to edit it · scroll wheel to move through the day",
