", ≈ {} nmol/L": ", ≈ {} nmol/L",
"Estimation à partir de ta prise de sang ({} nmol/L le matin), du rythme de la journée (environ 20 % plus bas le soir, Brambilla et coll. 2009) et des jours depuis ton dernier moment solo (Jiang et coll. 2003 : rien du 2e au 5e jour, pic vers 145 % le 7e jour, puis retour à la normale). Ce n'est pas une mesure : seule une prise de sang le dit vraiment.": "Estimate based on your blood test ({} nmol/L in the morning), the daily rhythm (about 20% lower in the evening, Brambilla et al. 2009) and the days since your last solo time (Jiang et al. 2003: nothing from day 2 to day 5, peak around 145% on day 7, then back to normal). It isn't a measurement: only a blood test really tells.",
