"Poids moyen": "Average weight",
"Ta semaine en chiffres · 7 derniers jours": "Your week in numbers · last 7 days",
"Entre parenthèses : l'écart avec les 7 jours d'avant. Calculé par l'appli à partir de tes mesures Garmin et Withings, sans IA.": "In brackets: the difference with the previous 7 days. Calculated by the app from your Garmin and Withings measurements, without AI.",
"de face": "front",
"de dos": "back",
"Mise en route": "Getting going",
"Marche ou vélo très léger : le sang circule, les muscles se relâchent mieux ensuite.": "Walking or very easy cycling: blood flows, the muscles then relax better.",
"Allongé, inspire 4 s par le ventre, expire 6 s. Le cœur ralentit, le corps passe en mode récupération.": "Lying down, breathe in 4 s through the belly, breathe out 6 s. The heart slows down, the body switches to recovery mode.",
"Assis ou allongé, le ventre monte à l'inspiration (4 s) et redescend à l'expiration (6 s). Le corps se détend avant de bouger la zone.": "Seated or lying down, the belly rises on the inhale (4 s) and falls on the exhale (6 s). The body relaxes before you move the area.",
"Mobilité douce ·": "Gentle mobility ·",
"Bouge la zone lentement dans l'amplitude sans douleur, 10 à 15 fois. Si ça dépasse 3/10, réduis l'amplitude.": "Move the area slowly through the pain-free range, 10 to 15 times. If it goes above 3/10, reduce the range.",
"Contraction légère tenue ·": "Light held contraction ·",
"Contracte le muscle de la zone à environ 30 % de ta force, 5 fois 20 s, sans douleur. Une contraction tenue calme souvent la douleur sur le moment (Rio et coll. 2015).": "Contract the muscle in the area at about 30% of your strength, 5 times 20 s, without pain. A held contraction often calms the pain in the moment (Rio et al. 2015).",
"Bouillotte ou douche chaude sur la zone. Pas de chaleur sur un choc récent qui a gonflé.": "Hot water bottle or hot shower on the area. No heat on a recent knock that has swollen.",
"Inspire 4 s, expire 6 s, 2 min. La douleur se perçoit moins quand le corps est calme.": "Breathe in 4 s, breathe out 6 s, 2 min. Pain is felt less when the body is calm.",
