"Les « ondes » (sons binauraux) ne sont pas proposées : leurs effets mesurés sont faibles et peu fiables (Garcia-Argibay et coll. 2019, méta-analyse).": "\"Waves\" (binaural beats) aren't offered: their measured effects are weak and unreliable (Garcia-Argibay et al. 2019, meta-analysis).",
