"Semaine {} de la saison": "Week {} of the season",
"Une douleur récente ou en hausse : les chiffres conseillent de repasser un temps en « {} », le temps qu'elle redescende. Ce n'est pas un retour en arrière, c'est ce qui protège tout le travail déjà fait. Parles-en à ton kiné.": "Recent or rising pain: the numbers suggest going back to \"{}\" for a while, until it settles. It isn't a step backwards, it's what protects all the work already done. Talk to your physio about it.",
"Vers l'étape « {} »": "Towards the \"{}\" stage",
"Pour continuer à progresser": "To keep progressing",
"Tu es revenu au sprint et ta charge progresse dans les clous. Bravo pour tout le chemin parcouru.": "You're back to sprinting and your load is progressing within the limits. Well done for how far you've come.",
"Tu es revenu au sprint. Garde un œil sur les critères pour progresser sans te blesser.": "You're back to sprinting. Keep an eye on the criteria to progress without getting injured.",
"Tous les voyants sont au vert : tu as fait le travail pour passer à l'étape suivante. Valide-la avec ton kiné.": "All the lights are green: you've done the work to move to the next stage. Confirm it with your physio.",
