"Les calculs": "The calculations",
": VFC de la nuit et moyenne 7 jours comparées à ta base 60 jours (45 %), sommeil par rapport à ton besoin de {} h (35 %), FC au repos (20 %). Moins 15 points si la respiration ou la température cutanée signalent une infection. Seuils faible / modérée / élevée à 34 et 67 %, comme Whoop.": ": overnight HRV and 7-day average compared with your 60-day baseline (45%), sleep relative to your need of {} h (35%), resting HR (20%). Minus 15 points if breathing or skin temperature signal an infection. Low / moderate / high thresholds at 34 and 67%, like Whoop.",
"Tes zones": "Your ranges",
": VFC et FC repos = moyenne 7 jours comparée à ta base 60 jours ± 0,5 écart-type (le plus petit changement qui a un sens, Plews et Buchheit). Sommeil = 8 à 10 h, la recommandation pour les athlètes. Respiration = ta moyenne ± 1 par minute. Le poids et la composition n'ont pas de zone : leur tendance suffit.": ": HRV and resting HR = 7-day average compared with your 60-day baseline ± 0.5 standard deviation (the smallest change that means something, Plews and Buchheit). Sleep = 8 to 10 h, the recommendation for athletes. Breathing = your average ± 1 per minute. Weight and composition have no range: their trend is enough.",
"Effort de 0 à 21": "Strain from 0 to 21",
": charge cardio de la montre (TRIMP, à partir de ta FC repos et de ta FC max de {} bpm) plus le RPE × durée de la muscu et du sprint que tu notes.": ": cardio load from the watch (TRIMP, based on your resting HR and your max HR of {} bpm) plus the RPE × duration of gym and sprint that you log.",
"Effort conseillé": "Suggested strain",
": selon tes jours d'entraînement (": ": depending on your training days (",
") et ta récupération du matin.": ") and your morning recovery.",
"Ignoré volontairement": "Deliberately ignored",
": statut d'entraînement, VO2max estimée, Body Battery, scores de sommeil et statut VFC calculés par Garmin ou Withings.": ": training status, estimated VO2max, Body Battery, sleep scores and HRV status calculated by Garmin or Withings.",
"Ton coucher vient de ton planning, ton besoin de sommeil se règle dans Sommeil. Apparence, protocole et connexions : menu de l'accueil.": "Your bedtime comes from your schedule, your sleep need is set in Sleep. Appearance, protocol and connections: home menu.",
