"ce que tu as fait": "what you did",
"comment ton corps a répondu": "how your body responded",
"« Part de la note » : le poids de l'élément dans l'anneau, fixé selon la solidité des preuves. « Atteint » : où tu en es. Points = part × atteint ; leur somme fait la note. Si un élément manque (pas de questionnaire, montre non portée), les autres se partagent sa part.": "\"Share of the score\": the weight of the item in the ring, set according to the strength of the evidence. \"Reached\": where you're at. Points = share × reached; their sum makes the score. If an item is missing (no check-in, watch not worn), the others share its part.",
"Pourquoi ces éléments": "Why these items",
"· chez des athlètes d'athlétisme d'élite suivis 5 ans, ceux qui font plus de 80 % des semaines prévues ont 7 fois plus de chances d'atteindre leur objectif (Raysmith et Drew 2016). Il ne compte qu'une fois la journée finie, et pas quand ta note t'en libère.": "· in elite track and field athletes followed for 5 years, those who complete more than 80% of planned weeks are 7 times more likely to reach their goal (Raysmith and Drew 2016). It only counts once the day is over, and not when your note excuses you from it.",
"chez des athlètes d'athlétisme d'élite suivis 5 ans, ceux qui font plus de 80 % des semaines prévues ont 7 fois plus de chances d'atteindre leur objectif (Raysmith et Drew 2016). Il ne compte qu'une fois la journée finie, et pas quand ta note t'en libère.": "in elite track and field athletes followed for 5 years, those who complete more than 80% of planned weeks are 7 times more likely to reach their goal (Raysmith and Drew 2016). It only counts once the day is over, and not when your note excuses you from it.",
"· la régularité du coucher et du lever prédit mieux la santé que la durée seule (Windred et coll. 2024, 61 000 personnes).": "· consistency of bedtime and wake-up time predicts health better than duration alone (Windred et al. 2024, 61,000 people).",
"la régularité du coucher et du lever prédit mieux la santé que la durée seule (Windred et coll. 2024, 61 000 personnes).": "consistency of bedtime and wake-up time predicts health better than duration alone (Windred et al. 2024, 61,000 people).",
"· une seule note : ta réponse du soir (au plan, minime, petit écart, repas libre), proposée d'après ton journal. Fruits, légumes et protéines maigres ajoutés ne comptent pas comme un écart. Ton menu est construit au-dessus de 1,6 g de protéines par kg, là où les gains de muscle plafonnent (Morton et coll. 2018, méta-analyse de 49 essais) : le suivre suffit.": "· a single score: your evening answer (on plan, minimal, small deviation, free meal), suggested from your log. Added fruit, vegetables and lean protein don't count as a deviation. Your menu is built above 1.6 g of protein per kg, where muscle gains plateau (Morton et al. 2018, meta-analysis of 49 trials): following it is enough.",
"une seule note : ta réponse du soir (au plan, minime, petit écart, repas libre), proposée d'après ton journal. Fruits, légumes et protéines maigres ajoutés ne comptent pas comme un écart. Ton menu est construit au-dessus de 1,6 g de protéines par kg, là où les gains de muscle plafonnent (Morton et coll. 2018, méta-analyse de 49 essais) : le suivre suffit.": "a single score: your evening answer (on plan, minimal, small deviation, free meal), suggested from your log. Added fruit, vegetables and lean protein don't count as a deviation. Your menu is built above 1.6 g of protein per kg, where muscle gains plateau (Morton et al. 2018, meta-analysis of 49 trials): following it is enough.",
"· déshydraté, tu perds environ 5,5 % de force et 5,8 % de puissance (Savoie et coll. 2015, méta-analyse). La quantité bue n'est qu'un repère, d'où sa petite part.": "· dehydrated, you lose about 5.5% of strength and 5.8% of power (Savoie et al. 2015, meta-analysis). The amount drunk is only a guide, hence its small share.",
"déshydraté, tu perds environ 5,5 % de force et 5,8 % de puissance (Savoie et coll. 2015, méta-analyse). La quantité bue n'est qu'un repère, d'où sa petite part.": "dehydrated, you lose about 5.5% of strength and 5.8% of power (Savoie et al. 2015, meta-analysis). The amount drunk is only a guide, hence its small share.",
"· fatigue, courbatures, sommeil ressenti, stress, humeur : chez les athlètes, ces réponses suivent la charge d'entraînement mieux que les mesures objectives (Saw et coll. 2016, revue de 56 études). D'où la plus grosse part.": "· fatigue, soreness, perceived sleep, stress, mood: in athletes, these answers track training load better than objective measurements (Saw et al. 2016, review of 56 studies). Hence the biggest share.",
"fatigue, courbatures, sommeil ressenti, stress, humeur : chez les athlètes, ces réponses suivent la charge d'entraînement mieux que les mesures objectives (Saw et coll. 2016, revue de 56 études). D'où la plus grosse part.": "fatigue, soreness, perceived sleep, stress, mood: in athletes, these answers track training load better than objective measurements (Saw et al. 2016, review of 56 studies). Hence the biggest share.",
"· ta note Recovery du matin, reprise telle quelle : VFC comparée à ta normale de 60 jours (45 %, Plews et coll. 2013), sommeil par rapport à ton besoin (35 %, Craven et coll. 2022 : une nuit écourtée = −7,6 % de performance), FC de repos (20 %, Buchheit 2014). Pas de double calcul.": "· your morning Recovery score, taken as is: HRV compared with your 60-day normal (45%, Plews et al. 2013), sleep relative to your need (35%, Craven et al. 2022: a shortened night = −7.6% performance), resting HR (20%, Buchheit 2014). No double counting.",
"ta note Recovery du matin, reprise telle quelle : VFC comparée à ta normale de 60 jours (45 %, Plews et coll. 2013), sommeil par rapport à ton besoin (35 %, Craven et coll. 2022 : une nuit écourtée = −7,6 % de performance), FC de repos (20 %, Buchheit 2014). Pas de double calcul.": "your morning Recovery score, taken as is: HRV compared with your 60-day normal (45%, Plews et al. 2013), sleep relative to your need (35%, Craven et al. 2022: a shortened night = −7.6% performance), resting HR (20%, Buchheit 2014). No double counting.",
"· suivie chaque jour comme dans le questionnaire de blessure OSTRC (Clarsen et coll. 2020).": "· tracked every day as in the OSTRC injury questionnaire (Clarsen et al. 2020).",
"suivie chaque jour comme dans le questionnaire de blessure OSTRC (Clarsen et coll. 2020).": "tracked every day as in the OSTRC injury questionnaire (Clarsen et al. 2020).",
"Ce score résume des éléments prouvés un par un ; le score lui-même n'a pas été validé tel quel par une étude. Regarde surtout sa tendance sur plusieurs semaines.": "This score sums up items each proven on their own; the score itself hasn't been validated as such by a study. Look mostly at its trend over several weeks.",
"({} %, poids {})": "({}%, weight {})",
": ce que tu as fait pour ton objectif.": ": what you did for your goal.",
": comment ton corps a répondu.{}Chaque élément est retenu pour la solidité de ses preuves chez les athlètes, et son poids suit cette solidité ; le détail et les études sont dans le score de l'accueil. Le coucher compte le soir même : le score se met à jour le lendemain matin.": ": how your body responded.{}Each item is chosen for the strength of its evidence in athletes, and its weight follows that strength; the details and studies are in the home score. Bedtime counts the same evening: the score updates the next morning.",
