"Fièvre : pas d'entraînement aujourd'hui. Repos, eau et sommeil ; reprends quand la fièvre est partie depuis 24 h.": "Fever: no training today. Rest, water and sleep; resume once the fever has been gone for 24 h.",
"Douleur forte ({} {}/10) : pas de sprint maximal ni de charge sur la zone. Les séances te proposeront des adaptations.": "Strong pain ({} {}/10): no max sprinting or load on the area. Sessions will suggest adaptations.",
"Signes de maladie : séance allégée, sans intensité maximale. Au-dessus du cou seulement (nez, gorge) : on peut s'entraîner léger ; ailleurs, repos.": "Signs of illness: lighter session, no maximal intensity. Above the neck only (nose, throat): you can train lightly; elsewhere, rest.",
"Gêne à {} ({}/10) : garde la séance, adapte ce qui charge la zone. Pendant l'effort, pas plus de 3/10.": "Discomfort at {} ({}/10): keep the session, adapt what loads the area. During effort, no more than 3/10.",
"Corps et tête fatigués ce matin : garde la séance mais baisse le volume, et couche-toi tôt ce soir.": "Body and mind tired this morning: keep the session but lower the volume, and go to bed early tonight.",
"Jambes lourdes ou courbatures : échauffement plus long, et pas de sprint maximal si ça ne s'améliore pas après.": "Heavy legs or soreness: longer warm-up, and no max sprinting if it doesn't improve afterwards.",
