"Plots au sol à écart régulier : reste grand, le pied se pose sous le bassin, chaque appui sur l'avant du pied.": "Cones on the ground at regular intervals: stay tall, the foot lands under the hips, every contact on the forefoot.",
"Jambe d'attaque sur le côté des haies": "Lead leg over the side of the hurdles",
