"Omoplates serrées, haltères qui descendent à hauteur de poitrine.": "Shoulder blades squeezed, dumbbells come down to chest height.",
"Banc à 30°, coudes à 45° du corps.": "Bench at 30°, elbows at 45° from the body.",
"Mains largeur d'épaules, coudes près du corps.": "Hands shoulder-width apart, elbows close to the body.",
"Allongé au sol, les coudes touchent le sol à chaque répétition.": "Lying on the floor, the elbows touch the floor on every rep.",
"Assis ou debout, pousse sans cambrer.": "Seated or standing, press without arching.",
"Paumes vers toi en bas, tourne les poignets en montant.": "Palms facing you at the bottom, rotate the wrists as you press.",
"Corps gainé, poitrine qui frôle le sol.": "Body braced, chest brushing the floor.",
"Buste incliné vers l'avant pour cibler les pectoraux.": "Torso leaning forward to target the chest.",
"Bras légèrement fléchis, ramène les mains devant toi.": "Arms slightly bent, bring your hands together in front of you.",
