"Poignées à hauteur de poitrine, pousse sans verrouiller.": "Handles at chest height, press without locking out.",
"Coudes fixes, écarte la corde en bas.": "Elbows fixed, spread the rope at the bottom.",
"Barre EZ": "EZ bar",
"Coudes vers le plafond, la barre descend vers le front.": "Elbows to the ceiling, the bar comes down towards the forehead.",
"Haltère derrière la tête, coudes serrés, déplie les bras.": "Dumbbell behind the head, elbows tight, extend the arms.",
"Buste penché, coude collé, tends le bras vers l'arrière.": "Torso bent forward, elbow tucked, extend the arm backwards.",
"Paumes vers toi, menton au-dessus de la barre.": "Palms facing you, chin over the bar.",
