"Squat isométrique contre le rack": "Isometric squat against the rack",
"Barre bloquée sous les sécurités : pousse au maximum 3 à 5 s, angle de genou choisi.": "Bar locked under the safeties: push as hard as possible for 3 to 5 s, at the chosen knee angle.",
"Tirage isométrique mi-cuisse": "Isometric mid-thigh pull",
"Barre bloquée à mi-cuisse : tire au maximum 3 à 5 s, dos neutre.": "Bar locked at mid-thigh: pull as hard as possible for 3 to 5 s, neutral back.",
"Rowing au TRX": "TRX row",
