"Fléchisseurs de hanche, posture": "Hip flexors, posture",
"Version marchée de l'A-skip : genou haut, pied flex qui revient sous le bassin, bras opposé.": "Walking version of the A-skip: knee high, dorsiflexed foot coming back under the hips, opposite arm.",
"Cycle de jambe": "Leg cycle",
"A-skip courue : fréquence rapide, genou haut, appuis brefs sous le centre de gravité.": "Running A-skip: fast frequency, knee high, brief contacts under the centre of mass.",
"Ischios, griffé": "Hamstrings, pawing",
"B-skip courue : la jambe se déplie puis griffe le sol vers l'arrière, sans traîner.": "Running B-skip: the leg extends then paws the ground backwards, without dragging.",
"Pied actif, mollets": "Active foot, calves",
