"Douleur notée : {}, {}/10.": "Pain logged: {}, {}/10.",
"Ta {} était prévue à {} et elle n'est pas notée. Si tu l'as faite, note-la dans ton questionnaire : je passe alors à la séance suivante.": "Your {} was planned for {} and it isn't logged. If you did it, log it in your check-in: I'll then move on to the next session.",
"Pas de séance à venir cette semaine : bouge la zone sans douleur et note son évolution chaque soir.": "No session coming up this week: move the area without pain and note how it evolves every evening.",
"la zone": "the area",
"très sollicités": "heavily loaded",
"sollicités": "loaded",
"Sprint de {} : {} {} à pleine vitesse. Courir à 85 % au lieu du maximum, accélérations de 30 m au plus, et un tiers de répétitions en moins": "Sprint on {}: {} {} at full speed. Run at 85% instead of max, accelerations of 30 m at most, and a third fewer reps",
"en soutien": "in support",
"ta {} et ton sprint": "your {} and your sprint",
"ta": "your",
"ton sprint": "your sprint",
"Rien dans {} ne charge cette zone : fais-la normalement et surveille la douleur à l'échauffement.": "Nothing in {} loads this area: do it normally and watch the pain during the warm-up.",
"Dans {}, du plus risqué au moins risqué :": "In {}, from most to least risky:",
"Choisir": "Choose",
"Choisir une date": "Choose a date",
