"de musculation": "strength",
"Crée une séance : elle apparaîtra ici, prête à être posée sur un jour.": "Create a session: it will appear here, ready to be placed on a day.",
"Crée tes séances sur ordinateur : elles apparaîtront ici, prêtes à être posées sur un jour.": "Create your sessions on a computer: they will appear here, ready to be placed on a day.",
"Attrape une séance et lâche-la sur un jour de la saison. Lâchée sur « Archiver », elle quitte la liste (tu peux la remettre depuis « Archive »). Une séance déjà posée se déplace de la même façon ; lâchée hors des jours, elle est retirée. Un clic sur une séance l'ouvre.": "Grab a session and drop it on a day of the season. Dropped on \"Archive\", it leaves the list (you can bring it back from \"Archive\"). A session already placed moves the same way; dropped outside the days, it's removed. A click on a session opens it.",
