"Intensité et volume": "Intensity and volume",
"Ta tendance apparaîtra ici": "Your trend will appear here",
"Termine ta première séance : intensité, volume et charge par muscle se calculent tout seuls.": "Finish your first session: intensity, volume and load per muscle are calculated automatically.",
"unités de charge": "load units",
"Muscu et sprint ensemble, avec ta charge par muscle.": "Gym and sprint together, with your load per muscle.",
"Tonnage, et intensité = charge moyenne en % de ton max.": "Tonnage, and intensity = average load as % of your max.",
"Mètres de sprint, et intensité = % moyen de ta vitesse.": "Sprint metres, and intensity = average % of your speed.",
