"à changer bientôt": "to change soon",
"Intensité": "Intensity",
"Tonnage en musculation": "Strength tonnage",
"Charge × répétitions de toutes tes séries, en tonnes.": "Load × reps of all your sets, in tonnes.",
"Mètres de sprint, sans les gammes ni l'échauffement. Règle : pas plus de +15 % d'une semaine à l'autre.": "Sprint metres, without drills or warm-up. Rule: no more than +15% from one week to the next.",
"Charge des ischios par rapport aux quadriceps {}. Pour un sprinteur, au moins 0,6 et plus c'est mieux : des ischios forts protègent des déchirures en vitesse.": "Hamstring load relative to quads {}. For a sprinter, at least 0.6 and more is better: strong hamstrings protect against tears at speed.",
"Ajoute 2 à 3 séries de nordic, leg curl ou soulevé de terre roumain, et enlève un peu de volume de squat ou de presse.": "Add 2 to 3 sets of Nordics, leg curls or Romanian deadlifts, and drop a little squat or leg press volume.",
"Les extenseurs de la hanche (fessiers) contre ses fléchisseurs (psoas) {}. En sprint, les deux travaillent à chaque foulée ; les fessiers restent au-dessus.": "Hip extensors (glutes) against its flexors (psoas) {}. In sprinting, both work on every stride; the glutes stay on top.",
"Si le psoas domine : plus de hip thrust et de fentes. Si les fessiers écrasent tout et que la hanche tire devant : ajoute des montées de genou lestées.": "If the psoas dominates: more hip thrusts and lunges. If the glutes overpower everything and the front of the hip pulls: add weighted knee drives.",
"L'intérieur de la cuisse contre l'extérieur de la hanche {}. Des adducteurs trop faibles par rapport aux abducteurs (moins de 0,8) multiplient les pubalgies et déchirures de l'aine (Tyler 2001).": "Inner thigh against outer hip {}. Adductors that are too weak relative to the abductors (below 0.8) multiply groin pain and groin tears (Tyler 2001).",
"Sous 0,8 : Copenhague, adducteurs à la machine. Au-dessus de 1,8 : abductions et pont latéral pour le moyen fessier.": "Below 0.8: Copenhagen, adductor machine. Above 1.8: abductions and side bridge for the gluteus medius.",
"Les muscles qui poussent le pied vers le bas contre celui qui le relève {}. Le tibial reste plus petit, mais il doit travailler : il amortit chaque appui.": "The muscles that push the foot down against the one that lifts it {}. The tibialis stays smaller, but it has to work: it absorbs every contact.",
"Ajoute des relevés de pointe de pied (tibial à la kettlebell) 2 fois par semaine.": "Add toe raises (kettlebell tibialis) twice a week.",
"L'arrière du tronc contre l'avant {}. Avec ta spondylolyse, l'équilibre compte : des abdos et un transverse solides protègent les lombaires.": "Back of the trunk against the front {}. With your spondylolysis, balance matters: solid abs and transversus protect the lower back.",
"Si les lombaires dominent : plus de gainage et de dead bug, moins d'extensions. Si les abdos dominent : un peu de travail du dos en isométrie.": "If the lower back dominates: more core work and dead bugs, fewer extensions. If the abs dominate: a little isometric back work.",
"Les muscles qui tirent les épaules en arrière contre ceux qui les tirent en avant {}. Un dos au moins aussi chargé que les pectoraux garde les épaules saines.": "The muscles that pull the shoulders back against those that pull them forward {}. A back at least as loaded as the chest keeps the shoulders healthy.",
"Ajoute du rowing ou des tractions, ou à l'inverse du développé si le dos domine largement.": "Add rows or pull-ups, or conversely pressing if the back dominates by far.",
"L'avant du bras contre l'arrière {}. En sprint, les bras rythment la foulée : les deux comptent.": "Front of the arm against the back {}. In sprinting, the arms set the stride rhythm: both count.",
"Rééquilibre avec du curl ou des extensions triceps selon le côté qui manque.": "Rebalance with curls or triceps extensions depending on the side that's lacking.",
"sur 7 jours": "over 7 days",
"sur 30 jours": "over 30 days",
"sur 12 mois": "over 12 months",
"depuis le début": "since the start",
"30 jours": "30 days",
"12 mois": "12 months",
