"Latérale": "Lateral",
"Médiale": "Medial",
"Tirage (haut du corps)": "Pull (upper body)",
"Poussée (haut du corps)": "Push (upper body)",
"Pied et cheville": "Foot and ankle",
"Fessiers, ischios, érecteurs, mollets, soléaire, carré des lombes. Le moteur du sprint : elle pousse le sol vers l'arrière et étend la hanche.": "Glutes, hamstrings, erectors, calves, soleus, quadratus lumborum. The sprint engine: it pushes the ground backwards and extends the hip.",
"Quadriceps, psoas, abdominaux, tibial, pectoraux. Elle ramène la jambe vers l'avant et encaisse l'impact à chaque appui.": "Quads, psoas, abs, tibialis, chest. It brings the leg forward and absorbs the impact on every contact.",
"Moyen fessier, obliques, carré des lombes, fibulaires, pelvi-trochantériens. Elle tient le bassin à plat quand tu es sur une jambe.": "Gluteus medius, obliques, quadratus lumborum, peroneals, deep hip rotators. It keeps the pelvis level when you're on one leg.",
"Adducteurs. Ils stabilisent le bassin et le genou et participent au retour de la jambe.": "Adductors. They stabilise the pelvis and knee and help bring the leg back.",
"Grand dorsal, rhomboïdes, trapèzes, biceps, coiffe. Tient les épaules en arrière et donne le balancier des bras.": "Lats, rhomboids, traps, biceps, cuff. Keeps the shoulders back and gives the arm swing.",
"Pectoraux, épaules, triceps, dentelé. Pousse vers l'avant ; en sprint, le bras qui part devant.": "Chest, shoulders, triceps, serratus. Pushes forward; in sprinting, the arm that drives in front.",
"Transverse, carré des lombes, érecteurs. Le gainage qui transmet la force des jambes sans perte.": "Transversus, quadratus lumborum, erectors. The core that transmits leg force without loss.",
"Muscles du pied, fibulaires, tibial, soléaire. Le premier ressort au contact du sol.": "Foot muscles, peroneals, tibialis, soleus. The first spring at ground contact.",
