"test du": "test of",
"estimé avec tes séances dans cette salle": "estimated from your sessions at this gym",
"pas encore de donnée ici": "no data here yet",
"Avant le suivi par salle : {} kg estimés, salle non notée.": "Before per-gym tracking: {} kg estimated, gym not logged.",
"Ton max, salle par salle": "Your max, gym by gym",
"Une machine ne pèse pas pareil d'une salle à l'autre : chaque salle garde son max, pour ne jamais te proposer une charge faite ailleurs.": "A machine doesn't weigh the same from one gym to another: each gym keeps its own max, so you're never offered a load done elsewhere.",
"Ton test du": "Your test of",
"Estimé à partir de ta meilleure série": "Estimated from your best set",
"Fais une séance avec cet exercice ou note ton test.": "Do a session with this exercise or log your test.",
"Charge pour": "Load for",
"RPE 8 = il te reste 2 répétitions. Ta récupération du jour peut baisser la charge proposée en séance.": "RPE 8 = you have 2 reps left. Your recovery of the day can lower the load suggested in the session.",
"Ton max": "Your max",
"Tes max connus ·": "Your known maxes ·",
"pas encore de max": "no max yet",
"Un max par exercice : ton test s'il existe, sinon l'estimation de tes séries de 5 répétitions ou moins (avec le RPE noté). Touche un exercice pour noter un test ou calculer une charge.": "One max per exercise: your test if there is one, otherwise the estimate from your sets of 5 reps or fewer (with the RPE logged). Tap an exercise to log a test or calculate a load.",
"max par salle · pas encore de donnée": "max per gym · no data yet",
"estimé": "estimated",
"pas encore de donnée": "no data yet",
"Plus de {} appuis en une journée :": "More than {} contacts in one day:",
"Deux jours de pliométrie d'affilée : garde 48 h entre deux.": "Two plyometric days in a row: keep 48 h between them.",
"Limite : 120 à 140 appuis par séance pour un athlète confirmé, 2 à 3 séances par semaine, 48 à 72 h entre deux (Chu et Myer, Plyometrics, 2013 ; NSCA, Essentials of Strength Training and Conditioning). Soit 140 par jour et 360 par semaine. Comptés : les sauts (séries × répétitions), le travail technique en pliométrie (environ 4 appuis par minute) et en haies (environ 1,6 par minute). Les sprints n'y sont pas : ils sont dans la charge par muscle.": "Limit: 120 to 140 contacts per session for an experienced athlete, 2 to 3 sessions a week, 48 to 72 h between them (Chu and Myer, Plyometrics, 2013; NSCA, Essentials of Strength Training and Conditioning). That's 140 a day and 360 a week. Counted: jumps (sets × reps), plyometric technical work (about 4 contacts per minute) and hurdles (about 1.6 per minute). Sprints aren't included: they're in the load per muscle.",
"Charge de pliométrie max ·": "Max plyometric load ·",
"Appuis au sol": "Ground contacts",
"appuis sur {} au maximum · {} jour{} de pliométrie": "contacts out of {} at most · {} plyometric day{}",
"· déséquilibré": "· unbalanced",
"déséquilibré": "unbalanced",
"Équilibre": "Balance",
"Muscu, par série : répétitions × intensité (charge ÷ ton max, ou % tiré du RPE) × proximité de l'échec (RIR 3 = 1, RIR 0-1 = 1,15, RIR 5 = 0,7) × part du muscle (1 muscle principal, 0,5 à 0,75 aide, 0,25 stabilisateur). C'est la charge relative de Scott et al. (2016) corrigée par l'effort ressenti (Helms 2016, Refalo 2023). Sprint : mètres ÷ 10 × intensité × facteur de stress × part du muscle, tes coefficients. Les autres activités : TRIMP de la montre ou RPE × minutes (Foster 2001).": "Gym, per set: reps × intensity (load ÷ your max, or % from RPE) × proximity to failure (RIR 3 = 1, RIR 0-1 = 1.15, RIR 5 = 0.7) × muscle share (1 main muscle, 0.5 to 0.75 helper, 0.25 stabiliser). It's the relative load of Scott et al. (2016) corrected by perceived effort (Helms 2016, Refalo 2023). Sprint: metres ÷ 10 × intensity × stress factor × muscle share, your coefficients. Other activities: watch TRIMP or RPE × minutes (Foster 2001).",
"Charge par muscle ·": "Load per muscle ·",
"Limites par muscle": "Limits per muscle",
"par défaut": "default",
"Charge maximale sur 7 jours pour chaque muscle. Au-delà, l'appli te prévient.": "Maximum load over 7 days for each muscle. Beyond that, the app warns you.",
"Très impliqués": "Heavily involved",
"Moyennement impliqués": "Moderately involved",
"Faiblement impliqués": "Lightly involved",
"Part : 100 % = muscle moteur, chaque série compte 1 série pour lui ; 40 à 75 % = muscle d'appoint, chaque série compte environ une demi-série (Pelland et coll. 2024, méta-régression de 67 études sur le volume) ; sous 40 % = stabilisateur. Fatigue sur 10 = part × facteur de l'exercice ({} ici) : plus haut quand le muscle travaille étiré en freinant (soulevé de terre jambes tendues, nordic, sprint à pleine vitesse), car les dégâts musculaires et le temps de récupération y sont plus grands (Nosaka et Sakamoto 2001). La part entre dans ta charge par muscle, tes équilibres et tes tendances ; la fatigue dans la fatigue restante de chaque muscle.": "Share: 100% = prime mover, each set counts as 1 set for it; 40 to 75% = helper muscle, each set counts as about half a set (Pelland et al. 2024, meta-regression of 67 studies on volume); below 40% = stabiliser. Fatigue out of 10 = share × exercise factor ({} here): higher when the muscle works stretched while braking (stiff-leg deadlift, Nordic, full-speed sprinting), because muscle damage and recovery time are greater (Nosaka and Sakamoto 2001). Share goes into your load per muscle, your balances and your trends; fatigue into each muscle's remaining fatigue.",
