"Ta Body Scan mesure la masse grasse et la masse musculaire de chaque bras, de chaque jambe et du tronc. Elles s'afficheront ici, sur ton corps, avec leur évolution.": "Your Body Scan measures the fat mass and muscle mass of each arm, each leg and the trunk. They will show here, on your body, with how they change.",
