"Couleur : densité du segment, sa part de ton total comparée à la part habituelle de ce segment. Touche un segment pour voir sa tendance. Écart gauche / droite : bras {}, jambes {} ; au-delà de 10 % sur les jambes, un déséquilibre de force est probable.": "Colour: density of the segment, its share of your total compared with that segment's usual share. Tap a segment to see its trend. Left / right gap: arms {}, legs {}; above 10% on the legs, a strength imbalance is likely.",
"Mesures brutes de ta Body Scan (impédance segmentaire). Sur une période, chaque valeur est la moyenne de tes pesées ; l'écart est celui entre la première et la dernière. Sur une année ou plus, un point par semaine. Fiables pour suivre une tendance, le matin à jeun ; moins précises qu'une DEXA en valeur absolue. Poids, eau et autres mesures : dans Tendances.": "Raw measurements from your Body Scan (segmental impedance). Over a period, each value is the average of your weigh-ins; the change is between the first and the last. Over a year or more, one point per week. Reliable for tracking a trend, in the morning on an empty stomach; less accurate than a DEXA in absolute value. Weight, water and other measurements: in Trends.",
