": {} ng/mL le {}{}.{} Elles servent à fabriquer les globules rouges et à réparer les tissus.": ": {} ng/mL on {}{}.{} They're used to make red blood cells and repair tissue.",
"Pois chiches, haricots rouges ou verts, petits pois, champignons, et des légumes verts dans ta ratatouille : une portion par jour.": "Chickpeas, red or green beans, peas, mushrooms, and green vegetables in your ratatouille: one serving a day.",
"Légumes verts à feuilles (épinards, mâche, brocoli), lentilles ou pois chiches, avocat, agrumes : une portion par jour.": "Leafy green vegetables (spinach, lamb's lettuce, broccoli), lentils or chickpeas, avocado, citrus fruit: one serving a day.",
