"ng/mL le": "ng/mL on",
". Prise de sang {}, {} ({} %). Depuis :": ". Blood test {}, {} ({}%). Since then:",
", poisson gras {} fois par semaine. Estimée aujourd'hui à ≈ {} ng/mL, en route vers {}.": ", oily fish {} times a week. Estimated today at ≈ {} ng/mL, on the way to {}.",
"Jamais mesurée dans tes bilans. Dans le Nord, d'octobre à mars le soleil est trop bas pour que la peau en fabrique : le manque est fréquent chez les sportifs du Nord, même jeunes.": "Never measured in your results. In the North, from October to March the sun is too low for the skin to make it: deficiency is common in northern athletes, even young ones.",
"Œufs entiers, champignons exposés au soleil, laitages enrichis.": "Whole eggs, sun-exposed mushrooms, fortified dairy.",
"Poissons gras (sardines, maquereau, saumon) 2 fois par semaine, œufs entiers.": "Oily fish (sardines, mackerel, salmon) twice a week, whole eggs.",
"Tu prends déjà de la D3 : garde-la jusqu'en avril.": "You already take D3: keep it up until April.",
"L'hiver, l'alimentation seule suffit rarement : la D3 est un des rares compléments prouvés.": "In winter, diet alone is rarely enough: D3 is one of the few proven supplements.",
"Demande la 25-OH vitamine D au prochain bilan.": "Ask for 25-OH vitamin D at your next blood test.",
"Ferritine jamais mesurée.": "Ferritin never measured.",
"Demande-la au prochain bilan.": "Ask for it at your next blood test.",
"Ferritine {} ng/mL le {}{}.{} Chez le sportif, sous 35 la performance peut baisser avant l'anémie.": "Ferritin {} ng/mL on {}{}.{} In athletes, below 35 performance can drop before anaemia.",
"Viande rouge 2 fois par semaine, lentilles avec un kiwi ou une orange (la vitamine C aide l'absorption), pas de thé ni de café pendant le repas.": "Red meat twice a week, lentils with a kiwi or an orange (vitamin C helps absorption), no tea or coffee with the meal.",
"Oméga-3 (EPA et DHA)": "Omega-3 (EPA and DHA)",
"Pas de poisson gras dans ton menu. Les noix apportent des oméga-3 végétaux, mais le corps en tire très peu d'EPA et de DHA.": "No oily fish in your menu. Walnuts provide plant omega-3s, but the body gets very little EPA and DHA from them.",
"Comme tu ne manges pas de poisson : noix, graines de lin moulues ou de chia, huile de colza ; et, c'est le cas où un complément se justifie, un oméga-3 d'algues (EPA + DHA, 250 à 500 mg par jour).": "Since you don't eat fish: walnuts, ground linseed or chia seeds, rapeseed oil; and, this is the case where a supplement is justified, an algae omega-3 (EPA + DHA, 250 to 500 mg a day).",
"Sardines, maquereau ou saumon 2 fois par semaine, à la place d'une portion de poulet.": "Sardines, mackerel or salmon twice a week, instead of a portion of chicken.",
"sous la norme": "below range",
"dans le bas de la norme": "at the low end of the range",
"mmol/L le {} :": "mmol/L on {}:",
".{} La sueur en fait perdre, et la prise de sang le mesure mal (presque tout est dans les cellules).": ".{} Sweat makes you lose it, and a blood test measures it poorly (almost all of it is inside the cells).",
"Amandes et noix, chocolat noir, légumes secs, céréales complètes, une eau riche en magnésium.": "Almonds and walnuts, dark chocolate, pulses, whole grains, a magnesium-rich water.",
"pg/mL le {}{}.": "pg/mL on {}{}.",
"Viande, poisson, œufs, laitages.": "Meat, fish, eggs, dairy.",
"Énergie": "Energy",
"kg perdus en 3 semaines en t'entraînant. Manger trop peu pour sa charge (RED-S) freine la récupération, les hormones et l'os.": "kg lost in 3 weeks while training. Eating too little for your load (RED-S) slows recovery, hormones and bone.",
"Ajoute 200 à 300 kcal par jour, surtout en glucides autour des séances.": "Add 200 to 300 kcal a day, mostly carbs around sessions.",
"Peu de laitages dans ton menu.": "Little dairy in your menu.",
"Laitages, eau riche en calcium, sardines avec les arêtes, amandes.": "Dairy, calcium-rich water, sardines with the bones, almonds.",
"Ajoute ta prise de sang (Objectifs › Prises de sang) pour voir tes carences possibles.": "Add your blood test (Goals › Blood tests) to see your possible deficiencies.",
"Détails": "Details",
"Bien couverts d'après ta dernière prise de sang :": "Well covered according to your last blood test:",
"Le classement part de ta dernière prise de sang, puis tient compte de ce que tu as mangé depuis (ton journal, ou ton plan les jours non notés), de tes compléments et, pour la vitamine D, du soleil du Nord : presque rien d'octobre à mars dans le Nord. Plus la prise de sang est ancienne, moins elle pèse. Une carence que ton alimentation corrige descend dans la liste, puis passe « en voie de correction ». Ce sont des estimations : seule une nouvelle prise de sang confirme.": "The ranking starts from your last blood test, then takes into account what you've eaten since (your log, or your plan on unlogged days), your supplements and, for vitamin D, the northern sun: almost nothing from October to March in the North. The older the blood test, the less it weighs. A deficiency your diet corrects moves down the list, then becomes \"being corrected\". These are estimates: only a new blood test confirms.",
"Protéines sous l'objectif {} jours sur {} : ajoute une source au repas le plus léger.": "Protein below the goal {} days out of {}: add a source to the lightest meal.",
"Glucides trop bas {} jours intenses sur {} : ces jours-là, augmente le riz ou les pâtes.": "Carbs too low on {} hard days out of {}: on those days, increase the rice or pasta.",
"Eau sous l'objectif {} jours sur {} : finis tes deux gourdes avant le soir.": "Water below the goal {} days out of {}: finish your two bottles before the evening.",
