"Mets au moins un jour calme entre deux grosses journées, surtout après le sprint.": "Put at least one easy day between two big days, especially after sprinting.",
"Cale tes séances intenses les matins où la récup est verte, et décale-les si elle est rouge.": "Schedule your intense sessions on mornings when recovery is green, and move them if it's red.",
