"Réglages du départ": "Start settings",
"Moins de 100 ms après le coup = faux départ (règle World Athletics). Mesure au dixième de milliseconde, juste à quelques ms près (l'écran lit le doigt environ toutes les 4 ms). Le retard du haut-parleur du téléphone est déjà compté. Avec des écouteurs Bluetooth, mets leur retard (souvent 150 à 250 ms), ou mieux : le haut-parleur.": "Less than 100 ms after the gun = false start (World Athletics rule). Measured to a tenth of a millisecond, accurate to within a few ms (the screen reads the finger about every 4 ms). The phone speaker's delay is already counted. With Bluetooth earphones, enter their delay (often 150 to 250 ms), or better: use the speaker.",
"Flash au coup": "Flash on the gun",
"pas de départ vu": "no start seen",
