"Repose ton doigt pour un nouvel essai": "Put your finger back for a new attempt",
"Garde-le posé, et lève-le au coup de pistolet": "Keep it down, and lift it at the gun",
"Pose ton doigt ici, lève-le au coup": "Put your finger here, lift it at the gun",
"Moins de 100 ms = faux départ": "Less than 100 ms = false start",
"Valider le cadre": "Confirm the frame",
"Tracer le cadre": "Draw the frame",
"Téléphone sur trépied, de profil, à 2 ou 3 m des blocs ; zoome pour que tu remplisses le cadre. La précision dépend de la cadence mesurée : à 30 im/s, ± 17 ms ; à 60 im/s, ± 8 ms. Pour aller plus loin, filme avec l'appareil photo en « Pro vidéo » 1080p à 120 im/s, et importe la vidéo (onglet Vidéo importée) : ± 4 ms. Le cadre vert = la zone surveillée : toi seul dedans. Le bonhomme montre ce que le téléphone voit de ton corps ; il se met en pause pendant le départ pour ne pas gêner la mesure.": "Phone on a tripod, side-on, 2 or 3 m from the blocks; zoom so you fill the frame. Accuracy depends on the measured frame rate: at 30 fps, ± 17 ms; at 60 fps, ± 8 ms. To go further, film with the camera app in \"Pro video\" 1080p at 120 fps, and import the video (Imported video tab): ± 4 ms. The green frame = the watched area: only you inside it. The stick figure shows what the phone sees of your body; it pauses during the start so as not to disturb the measurement.",
