"Analyser le départ": "Analyse the start",
"« Choisir la personne » : trace un cadre autour d'elle seule, sur l'image du coup. Les autres couloirs ne comptent pas.": "\"Choose the person\": draw a frame around them alone, on the frame of the gun. The other lanes don't count.",
"Une vidéo avec le son du starter : le coup est retrouvé dans le son, puis le premier mouvement de la personne choisie, image par image. Plus la vidéo a d'images par seconde (ralenti), plus c'est précis.": "A video with the starter's sound: the gun is found in the audio, then the chosen person's first movement, frame by frame. The more frames per second the video has (slow-mo), the more accurate it is.",
