"Activée : Claude écrit l'analyse du matin et le bilan du vendredi, le bouton IA est en haut à droite.": "On: Claude writes the morning analysis and the Friday review, the AI button is at the top right.",
"Coupée : zéro IA. Tout ce que tu lis est calculé par le programme de l'appli à partir de tes données. Rien n'est envoyé à Claude.": "Off: zero AI. Everything you read is calculated by the app's own program from your data. Nothing is sent to Claude.",
"Coupe-la si tu n'as plus d'abonnement Claude : l'appli continue de tout calculer seule (récupération, charge, objectifs, conseils, bilans).": "Turn it off if you no longer have a Claude subscription: the app keeps calculating everything on its own (recovery, load, goals, advice, reviews).",
"Tes données (Garmin, Withings, tes saisies) continuent d'arriver normalement. Rallume quand tu veux.": "Your data (Garmin, Withings, your entries) keeps coming in normally. Turn it back on whenever you like.",
"Conseils des coachs": "Coaches' advice",
"Affichés : coach training, coach nutrition et coach recovery.": "Shown: training coach, nutrition coach and recovery coach.",
"Masqués : plus aucun conseil de coach dans Training, Nutrition et Recovery.": "Hidden: no more coach advice in Training, Nutrition and Recovery.",
"Très grande": "Very large",
"Les halos de couleur qui bougent doucement derrière les pages": "The colour halos that move gently behind the pages",
"Réduire les animations": "Reduce animations",
"Les pages changent sans glisser ni rebondir : plus calme, et plus rapide sur un vieux téléphone": "Pages change without sliding or bouncing: calmer, and faster on an old phone",
"Un petit retour quand tu touches les boutons et tires pour actualiser": "A little feedback when you tap buttons and pull to refresh",
"Va chercher Garmin et Withings à chaque ouverture": "Fetches Garmin and Withings every time it opens",
