"la plus précise": "the most accurate",
"mesure de la cadence…": "measuring the frame rate…",
"précision ± {} ms": "accuracy ± {} ms",
"Cadence basse : plus de lumière, « Pose courte », ou filme en Pro vidéo 120 im/s et importe la vidéo.": "Low frame rate: more light, \"Short exposure\", or film in Pro video 120 fps and import the video.",
"Téléphone sur trépied, de profil, à 2 ou 3 m des blocs ; zoome pour que tu remplisses le cadre. La précision dépend de la cadence : à 30 im/s ± 19 ms, à 60 im/s ± 10 ms. Dans un navigateur, Android ne donne pas plus de 60 im/s (le 120 et le 240 im/s sont réservés à l'appareil photo de Samsung). Pour le plus précis : filme en « Pro vidéo », 1080p, 120 im/s, et importe la vidéo (onglet Vidéo importée) : ± 6 ms. Le cadre vert = la zone surveillée : toi seul dedans. Le bonhomme montre ce que le téléphone voit de ton corps ; il se met en pause pendant le départ pour ne pas gêner la mesure.": "Phone on a tripod, side-on, 2 or 3 m from the blocks; zoom so you fill the frame. Accuracy depends on the frame rate: at 30 fps ± 19 ms, at 60 fps ± 10 ms. In a browser, Android gives no more than 60 fps (120 and 240 fps are reserved for Samsung's camera app). For the most accurate: film in \"Pro video\", 1080p, 120 fps, and import the video (Imported video tab): ± 6 ms. The green frame = the watched area: only you inside it. The stick figure shows what the phone sees of your body; it pauses during the start so as not to disturb the measurement.",
"Téléphone sur trépied, de profil, toi dans les blocs": "Phone on a tripod, side-on, you in the blocks",
"Précision ± {} ms · {} % · une image toutes les {} ms": "Accuracy ± {} ms · {}% · one frame every {} ms",
"▶ Ralenti": "▶ Slow-mo",
"· COUP": "· GUN",
"COUP": "GUN",
"PPS S1 · Force et contraste": "SPP W1 · Strength and contrast",
"Force max + sauts · semaine reprise": "Max strength + jumps · return week",
"Garder la force maximale et la rendre rapide : une charge lourde, puis des sauts juste après. Ordre : le plus lourd et le plus rapide d'abord (frais), puis les muscles du sprint, la prévention et le tronc à la fin. Environ 60 min.": "Keep maximal strength and make it fast: a heavy load, then jumps right after. Order: heaviest and fastest first (fresh), then the sprint muscles, prevention and core at the end. About 60 min.",
"En premier, frais : la charge la plus lourde de la semaine. Descente contrôlée, remontée la plus vite possible ; arrête la série si la barre ralentit nettement.": "First, fresh: the heaviest load of the week. Controlled descent, drive up as fast as possible; stop the set if the bar slows down clearly.",
"20 s après chaque série de squat (contraste) : le muscle lourd puis rapide. Box haute, réception douce, et tu redescends en marchant : aucun choc pour les tibias.": "20 s after each squat set (contrast): the muscle heavy then fast. High box, soft landing, and step back down: no impact for the shins.",
"Les fessiers, moteurs de l'accélération. Pause 1 s en haut, bassin verrouillé.": "The glutes, engines of acceleration. Pause 1 s at the top, hips locked.",
"Une jambe, descente en 3 s : les ischios en allongement, comme en fin de foulée. Remplace le nordic (rien sur les genoux ni les tibias).": "One leg, 3 s descent: the hamstrings lengthening, as at the end of the stride. Replaces the Nordic (nothing on the knees or shins).",
"Mollets assis : le soléaire, qui encaisse chaque appui. Sans impact.": "Seated calves: the soleus, which absorbs every contact. No impact.",
"Par côté. En dernier : le tronc qui résiste à la rotation, sans fatiguer les jambes.": "Per side. Last: the trunk resisting rotation, without tiring the legs.",
"PPS S1 · Puissance": "SPP W1 · Power",
"Épaulé, lancers, une jambe · semaine reprise": "Clean, throws, single leg · return week",
"La vitesse d'exécution : des charges moyennes déplacées le plus vite possible, puis la force sur une jambe. Peu de volume, toujours de la qualité. Environ 55 min.": "Speed of execution: medium loads moved as fast as possible, then single-leg strength. Little volume, always quality. About 55 min.",
"En premier : le geste le plus technique et le plus rapide. Chaque répétition explosive ; on s'arrête si la vitesse baisse.": "First: the most technical and fastest movement. Every rep explosive; stop if the speed drops.",
"Lancer arrière par-dessus la tête, tout le corps pousse comme au départ. La puissance sans réception au sol.": "Overhead backward throw, the whole body drives as at the start. Power without landing.",
"Par jambe, montée explosive : la force sur une jambe, comme en course.": "Per leg, explosive step-up: single-leg strength, as when running.",
"Dos neutre, hanches en arrière : ischios et fessiers en allongement.": "Neutral back, hips back: hamstrings and glutes lengthening.",
"Par côté : les adducteurs, protège le pubis et l'aine.": "Per side: the adductors, protects the pubis and groin.",
"Léger et sans douleur : renforcer le tibial antérieur aide contre les périostites. Saute-le si le tibia fait mal ce jour-là.": "Light and pain-free: strengthening the tibialis anterior helps against shin splints. Skip it if your shin hurts that day.",
"PPS S1 · Haut du corps et prévention": "SPP W1 · Upper body and prevention",
